create unique index if not exists schoolpro_candidate_answer_unique on public.schoolpro_candidate_cbt_answers(attempt_id,question_id);
create unique index if not exists schoolpro_candidate_assignment_unique on public.schoolpro_candidate_cbt_attempts(application_id,test_id);
create or replace function public.get_schoolpro_admission_offer(p_token uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare o public.schoolpro_admission_offers;a public.schoolpro_admissions;begin select * into o from public.schoolpro_admission_offers where public_token=p_token;if o.id is null then raise exception 'Invalid admission offer';end if;if o.expires_at is not null and now()>o.expires_at and o.status<>'accepted' then raise exception 'Admission offer expired';end if;select * into a from public.schoolpro_admissions where id=o.application_id;return jsonb_build_object('offer_number',o.offer_number,'offered_class',o.offered_class,'letter_body',o.letter_body,'issued_at',o.issued_at,'expires_at',o.expires_at,'status',o.status,'acceptance_instructions',o.acceptance_instructions,'applicant_name',a.applicant_name,'application_number',a.application_number);end$$;
revoke all on function public.get_schoolpro_admission_offer(uuid) from public;grant execute on function public.get_schoolpro_admission_offer(uuid) to anon,authenticated;
create or replace function public.accept_schoolpro_admission_offer(p_token uuid,p_name text,p_email text,p_notes text default null) returns jsonb language plpgsql security definer set search_path='' as $$declare o public.schoolpro_admission_offers;a public.schoolpro_admissions;begin select * into o from public.schoolpro_admission_offers where public_token=p_token for update;if o.id is null then raise exception 'Invalid admission offer';end if;if o.expires_at is not null and now()>o.expires_at then raise exception 'Admission offer expired';end if;if o.status='accepted' then return jsonb_build_object('accepted',true,'offer_number',o.offer_number);end if;if o.status not in('issued','offered','pending') then raise exception 'Offer cannot be accepted';end if;if nullif(trim(p_name),'') is null or position('@' in coalesce(p_email,''))=0 then raise exception 'Name and valid email required';end if;select * into a from public.schoolpro_admissions where id=o.application_id;insert into public.schoolpro_admission_acceptances(application_id,accepted_by_name,accepted_by_email,terms_accepted,notes) values(o.application_id,trim(p_name),lower(trim(p_email)),true,p_notes);update public.schoolpro_admission_offers set status='accepted',accepted_at=now() where id=o.id;update public.schoolpro_admissions set accepted_at=now(),status='accepted' where id=o.application_id;return jsonb_build_object('accepted',true,'offer_number',o.offer_number);end$$;
revoke all on function public.accept_schoolpro_admission_offer(uuid,text,text,text) from public;grant execute on function public.accept_schoolpro_admission_offer(uuid,text,text,text) to anon,authenticated;